function firstDeadlock(events) {
  const owner = new Map()
  const waitingFor = new Map()
  const lines = new Map()
  for (let index = 0; index < events.length; index++) {
    const [thread, action, lock] = events[index]
    if (action === 'release') {
      const line = lines.get(lock)
      if (line && line.length > 0) {
        const next = line.shift()
        waitingFor.delete(next)
        owner.set(lock, next)
      } else {
        owner.delete(lock)
      }
      continue
    }
    if (!owner.has(lock)) {
      owner.set(lock, thread)
      continue
    }
    waitingFor.set(thread, lock)
    if (!lines.has(lock)) lines.set(lock, [])
    lines.get(lock).push(thread)
    let holder = owner.get(lock)
    while (holder !== thread && waitingFor.has(holder)) holder = owner.get(waitingFor.get(holder))
    if (holder === thread) return index
  }
  return -1
}

