from collections import deque


def first_deadlock(events):
    owner = {}
    waiting_for = {}
    lines = {}
    for index, (thread, action, lock) in enumerate(events):
        if action == "release":
            line = lines.get(lock)
            if line:
                nxt = line.popleft()
                del waiting_for[nxt]
                owner[lock] = nxt
            else:
                del owner[lock]
            continue
        if lock not in owner:
            owner[lock] = thread
            continue
        waiting_for[thread] = lock
        lines.setdefault(lock, deque()).append(thread)
        holder = owner[lock]
        while holder != thread and holder in waiting_for:
            holder = owner[waiting_for[holder]]
        if holder == thread:
            return index
    return -1
